#include <stdio.h>


int main(void)
{
    int a[] = {4, 2, 1};
    int min = 0;
    for (int j = 1; j < 3; j++) {
        if (a[j] < a[min]) {
            min = j;
        }
    }
    printf("%d\n", min);
    return 0;
}

